const concept = $json.concepts;
const raw = $json.choices[0].message.content;
let cleaned = raw.trim();
cleaned = cleaned.replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim();
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error('AI response is not valid JSON | استجابة الذكاء الاصطناعي ليست JSON صالحاً: ' + e.message);
}
return { json: { ...concept, ...parsed } };
